import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import classList from 'flarum/common/utils/classList';
import { failed, storiesChanged, t, tx } from '../util';
import { openHighlightPicker, openReport } from './modals';
/** The viewer's ⋯ menu: what the viewer may do to this story, nothing they may not. */
export default class ViewerMenu extends Component {
  view() {
    const {
      story,
      own
    } = this.attrs;
    const items = [];
    if (own) items.push(['highlight', 'fa-star']);
    if (story.canReport()) items.push(['report', 'fa-flag']);
    if (!own && app.session.user) items.push(['mute', 'fa-volume-xmark']);
    items.push(['copy', 'fa-link']);
    if (story.canModerate() && !own) items.push(['hide', 'fa-eye-slash', true]);
    if (story.canDelete()) items.push(['delete', 'fa-trash', true]);
    return m("ul", {
      className: "GlimpseViewer-menu",
      role: "menu"
    }, items.map(([action, icon, danger]) => m("li", {
      role: "none"
    }, m("button", {
      type: "button",
      role: "menuitem",
      className: classList(danger && 'is-danger'),
      onclick: () => this.run(action)
    }, m("i", {
      className: classList('fas', icon),
      "aria-hidden": "true"
    }), ' ', t(`viewer.menu.${action}`, {
      name: (story.user() || null)?.displayName()
    })))));
  }
  run(action) {
    const {
      story,
      onsay,
      onclose
    } = this.attrs;
    const user = story.user() || null;
    const resume = () => onclose(true);
    if (action === 'report') {
      onclose(false);
      return openReport(story, () => onsay(tx('viewer.reported')), resume);
    }
    if (action === 'highlight') {
      onclose(false);
      return openHighlightPicker(story, title => onsay(tx('viewer.highlighted', {
        title
      })), resume);
    }
    if (action === 'mute' && user) return this.mute(user);
    if (action === 'copy') return this.copyLink();
    if (action === 'hide') return this.hide();
    if (action === 'delete') return this.remove();
  }
  mute(user) {
    this.attrs.onclose(false);
    app.store.createRecord('glimpse-mutes').save({
      relationships: {
        mutedUser: user
      }
    }).then(() => {
      this.attrs.onsay(tx('viewer.muted', {
        name: user.displayName()
      }));
      storiesChanged();
      window.setTimeout(() => this.attrs.onmuted(), 700);
    }, failed);
  }
  copyLink() {
    navigator.clipboard?.writeText(app.forum.attribute('baseUrl') + app.route('glimpse.story', {
      id: this.attrs.story.id()
    })).then(() => this.attrs.onsay(tx('viewer.copied'))).catch(() => this.attrs.onsay(tx('viewer.copy_failed')));
    this.attrs.onclose(true);
  }
  hide() {
    this.attrs.story.save({
      status: 'hidden'
    }).then(() => {
      this.attrs.onsay(tx('viewer.hidden'));
      storiesChanged();
      this.attrs.onclose(true);
    }, failed);
  }
  remove() {
    if (!confirm(tx('viewer.delete_confirm'))) return this.attrs.onclose(true);
    this.attrs.onclose(false);
    this.attrs.story.delete().then(() => {
      this.attrs.onsay(tx('viewer.deleted'));
      storiesChanged();
      this.attrs.ondeleted();
    }, failed);
  }
}
flarum.reg.add('ernestdefoe-glimpse', 'forum/ui/ViewerMenu', ViewerMenu);